export const svgToDataUri = (svgString) => {
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svgString);
};

export const TYPOGRAPHY_PREVIEW_URIS = {
  'typography-svg-1': svgToDataUri(RAW_SVG_1),
  'typography-svg-2': svgToDataUri(RAW_SVG_2),
  'typography-svg-3': svgToDataUri(RAW_SVG_3),
  'typography-svg-4': svgToDataUri(RAW_SVG_4),
  'typography-svg-5': svgToDataUri(RAW_SVG_5)
};

export const parseSvgStringToGroupNode = (rawSvg, name, targetWidth, targetHeight, cx, cy) => {
  const uniqueId = 'group-typography-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
  const parser = new DOMParser();
  const doc = parser.parseFromString(rawSvg, 'image/svg+xml');
  const svgEl = doc.querySelector('svg');

  if (!svgEl) return null;

  const vb = svgEl.getAttribute('viewBox');
  let originalWidth = 100;
  let originalHeight = 100;

  if (vb) {
    const parts = vb.trim().split(/[\s,]+/).map(Number);
    if (parts.length === 4 && parts[2] > 0 && parts[3] > 0) {
      originalWidth = parts[2];
      originalHeight = parts[3];
    }
  } else {
    originalWidth = parseFloat(svgEl.getAttribute('width')) || 100;
    originalHeight = parseFloat(svgEl.getAttribute('height')) || 100;
  }

  const scale = targetWidth / originalWidth;
  const computedHeight = originalHeight * scale;
  const posX = Math.round(cx - targetWidth / 2);
  const posY = Math.round(cy - computedHeight / 2);

  const group = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  group.setAttribute('id', uniqueId);
  group.setAttribute('data-type', 'group');
  group.setAttribute('data-is-element-typography', 'true');
  group.setAttribute('data-subtopic', 'Typography');
  group.setAttribute('data-name', name);
  group.setAttribute('transform', `translate(${posX}, ${posY}) scale(${scale.toFixed(4)})`);

  const innerGroup = svgEl.querySelector('g');
  if (innerGroup) {
    Array.from(innerGroup.childNodes).forEach((child) => {
      group.appendChild(document.importNode(child, true));
    });
  } else {
    Array.from(svgEl.childNodes).forEach((child) => {
      group.appendChild(document.importNode(child, true));
    });
  }

  return group;
};
